INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_pat_event_data_template','input_params','','json_build_array (VARIADIC ARRAY [json_build_object ( ''item_json'', json_build_object(), ''field_name'', ''{env_fieldName}'', ''is_rst_copy'', '''', ''format_class'', 1, ''is_field_display'', ''1'' ),json_build_object (''item_json'',json_build_object ( ''values'', json_build_array ( VARIADIC ARRAY [ {env_name} ] ), ''image_num'', ''{env_imageNum}'', ''image_col_num'', ''{env_imageColNum}'' ),''field_name'',''{env_fieldName}'',''is_rst_copy'',''2'',''format_class'',2,''is_field_display'',''1'' ),json_build_object ( ''item_json'', json_build_object(), ''field_name'', ''{env_fieldName}'', ''is_rst_copy'', '''', ''format_class'', 3, ''is_field_display'', ''0'' ),json_build_object ( ''item_json'', json_build_object(), ''field_name'', '''', ''is_rst_copy'', '''', ''format_class'', 4, ''is_field_display'', ''0'' ),json_build_object ( ''item_json'', json_build_object(), ''field_name'', ''{env_fieldName}'', ''is_rst_copy'', '''', ''format_class'', 5, ''is_field_display'', ''0'' ),json_build_object ( ''item_json'', json_build_object(), ''field_name'', ''{env_fieldName}'', ''is_rst_copy'', '''', ''format_class'', 6, ''is_field_display'', ''0'' ),json_build_object ( ''item_json'', json_build_object(), ''field_name'', ''{env_fieldName}'', ''is_rst_copy'', '''', ''format_class'', 7, ''is_field_display'', ''1'' ),json_build_object ( ''item_json'', json_build_object(), ''field_name'', ''{env_fieldName}'', ''is_rst_copy'', '''', ''format_class'', 8, ''is_field_display'', ''0'' ) ] ) :: jsonb','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_pat_event_sub_category','template_cd','','(CASE ''{category_cd}'' WHEN ''-1'' THEN CASE ''{fn_event_category_cd_2}'' WHEN ''0'' THEN (select template_cd from mst_pat_event_data_template where facility_cd=''{facility_cd}'' and fn_template_cd=''-3'') ELSE (select template_cd from mst_pat_event_data_template where facility_cd=''{facility_cd}'' and fn_template_cd=''-4'') END ELSE (select template_cd from mst_pat_event_data_template where facility_cd=''{facility_cd}'' and fn_template_cd= ''{fn_event_category_cd_2}'') END)','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'addition_info', 'cd', '(select addition_cd from mst_addition where facility_cd=''{facility_cd}'' and fn_add_cd= ''{cd}'')', '', '', 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES('mst_medicine_support','detail_info','','json_build_object(''medicineESA'',json_build_array(),''examItemAverage'', {examItemAverage},''examItemCycling'',(SELECT COALESCE(array_to_json(ARRAY_AGG(row_to_json(T))), ''[]'' ) FROM (SELECT exam_item_name AS text,unit, exam_item_cd AS value,json_build_array({examItemCyclingexamFlg}) as examflg FROM mst_exam_item WHERE facility_cd = ''{facility_cd}'' AND fn_exam_item_cd =''{examItemCyclingCd}'')T),''medicineAverage'',(SELECT COALESCE(array_to_json(ARRAY_AGG(row_to_json(T))), ''[]'' ) FROM (SELECT medicine_group_name AS text, 3 as type,medicine_group_cd AS value FROM mst_medicine_group WHERE facility_cd = ''{facility_cd}'' AND fn_medicine_group_cd in (SELECT unnest(string_to_array(''{medicineAverage}'', '',''))) order by array_positions(array[''{medicineAverage}''],fn_medicine_group_cd::TEXT) )T), ''initialRangeExam'', 3, ''examItemRegression'',json_build_array(), ''initialRangeMedicine'', 3)','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES('mst_medicine_support','examItemAverage','examflg','json_build_array({examflg})','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME, NTSS_COLUMN_NAME, NTSS_JSON_NAME, CONV_VALUE_1, CONV_VALUE_2, CONVERSION_TYPE) VALUES ('ord_coop_no', 'ord_no', '', '(CASE ''{coop_cd}'' WHEN ''profile'' THEN null WHEN ''ind_dial'' THEN (select ord_no from ord_main where facility_cd=''{facility_cd}'' and treat_date=(select substr(''{ord_no}'', 1, 8)) and fn_pat_id:: CHARACTER VARYING = substr(''{ord_no}'', 16, 12) and fn_plural:: TEXT = substr(''{ord_no}'', 28, 1):: TEXT LIMIT 1) ELSE ( CASE WHEN  {is_del} = 1 THEN (select ord_no from ord_main_restore where facility_cd=''{facility_cd}'' and rst_fn_dialysis_no=(select substr(''{ord_no}'', 0, 13):: int8))  ELSE (select ord_no from ord_main where facility_cd=''{facility_cd}'' and rst_fn_dialysis_no=(select substr(''{ord_no}'', 0, 13):: int8)) END)   END)', '', 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('pat_ind_approve','ord_no','','(select ord_no from ord_main where fn_pat_id=''{pat_id}'' and treat_date=''{treat_date}'' and fn_plural=''{plural}'' and facility_cd=''{facility_cd}'')','','SQL');
