INSERT INTO SYNC_CUSTOM_CONVERT_VALUE ( NTSS_TABLE_NAME, NTSS_COLUMN_NAME, NTSS_JSON_NAME, CONV_VALUE_1, CONV_VALUE_2, CONVERSION_TYPE )VALUES( 'mst_treatment_set', 'ind_cond_info', 'value', '(CASE ''{value}'' WHEN ''null'' THEN null else ((CASE WHEN''{key}'' IN (''25'') THEN CASE ''{medicine_type}'' WHEN ''0'' THEN (SELECT medicine_cd :: text FROM mst_medicine WHERE facility_cd = ''{facility_cd}'' AND trim(fn_medicine_cd) = substr(''{value}'',2)) WHEN ''1'' THEN (SELECT medicine_mix_cd :: text FROM mst_medicine_mix WHERE facility_cd = ''{facility_cd}'' AND fn_set_medicine_cd = substr(''{value}'',2)) END  WHEN''{key}'' IN (''15'', ''19'') THEN (SELECT medicine_cd :: text FROM mst_medicine WHERE facility_cd = ''{facility_cd}'' AND trim(fn_medicine_cd) = ''{value}'')  WHEN''{key}'' IN (''6'', ''7'', ''8'', ''9'', ''10'', ''13'') THEN (SELECT equipment_cd :: text from mst_equipment WHERE facility_cd = ''{facility_cd}'' AND fn_equipment_cd = ''{value}'') WHEN''{key}'' = ''11'' THEN (SELECT equipment_cd :: text from mst_equipment WHERE facility_cd = ''{facility_cd}'' AND fn_equipment_cd = CONCAT(''SN'', SUBSTRING(''{value}'', 3))) WHEN ''{key}'' = ''2'' THEN (SELECT va_cd :: text from mst_va WHERE facility_cd = ''{facility_cd}'' AND fn_va_cd = ''{value}'') WHEN ''{key}'' = ''5'' THEN (SELECT dialyzer_cd :: text from mst_dialyzer WHERE facility_cd = ''{facility_cd}'' AND fn_dialyzer_cd = ''{value}'') else ''{value}'' END)) END) ', '', 'SQL' );
