INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mnt_motion_record','ord_no','','(SELECT om.ord_no FROM ord_main om LEFT OUTER JOIN mst_bed mb ON om.rst_bed_cd=mb.bed_cd LEFT OUTER JOIN mst_machine mm ON om.rst_machine_no=mm.machine_no WHERE om.facility_cd=''{facility_cd}'' AND mm.fn_device_no=split_part(''{ord_no}'', '','', 1)::int AND om.rst_cond_send_date<=TO_TIMESTAMP(split_part(''{ord_no}'', '','', 2), ''YYYY-MM-DD HH24:MI:SS'') AND om.rst_end_date >=TO_TIMESTAMP(split_part(''{ord_no}'', '','', 2), ''YYYY-MM-DD HH24:MI:SS''))','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mnt_motion_record','machine_type_cd','','(SELECT CASE WHEN ''{device_type}'' = ''1'' THEN (SELECT machine_type_cd FROM mst_machine WHERE facility_cd = ''{facility_cd}'' AND fn_device_no = ''{machine_type_cd}'' AND fn_class_cd=''0'') ELSE (SELECT machine_type_cd FROM mst_machine WHERE facility_cd = ''{facility_cd}'' AND fn_device_no = ''{machine_type_cd}'' AND fn_class_cd=''1'') END)','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mnt_motion_record','machine_serial','','(SELECT CASE WHEN ''{device_type}'' = ''1'' THEN (SELECT machine_serial FROM mst_machine WHERE facility_cd = ''{facility_cd}'' AND fn_device_no = ''{machine_serial}'' AND fn_class_cd=''0'') ELSE (SELECT machine_serial FROM mst_machine WHERE facility_cd = ''{facility_cd}'' AND fn_device_no = ''{machine_serial}'' AND  fn_class_cd=''1'') END)','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mnt_motion_record','com_format_cd','','(SELECT CASE WHEN ''{device_type}'' = ''1'' THEN (SELECT com_format_cd FROM mst_machine WHERE facility_cd = ''{facility_cd}'' AND fn_device_no = ''{com_format_cd}'' AND fn_class_cd=''0'') ELSE (SELECT com_format_cd FROM mst_machine WHERE facility_cd = ''{facility_cd}'' AND fn_device_no = ''{com_format_cd}'' AND  fn_class_cd=''1'') END)','','SQL');
