INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_addition', 'addition_tar_cd', '', 'case when {addition_class} = 4 then (select coalesce(array_to_json (array_agg(row_to_json(t))),''[]'') from ( select treatment_cd AS cd, treatment_name AS name from mst_treatment where device_mode IN (''7'',''8'',''10'') and facility_cd = ''{facility_cd}'' and is_disp = ''1'') t) else case when ''{addition_tar_cd}'' is null or ''{addition_tar_cd}''=''''  THEN ''[]'' else json_build_array(json_build_object(''cd'',(select disease_cd from mst_disease where facility_cd = ''{facility_cd}'' AND fn_disease_cd = ''{addition_tar_cd}'' and fn_class_cd=''0''),''name'',(select disease_name from mst_disease where facility_cd = ''{facility_cd}'' AND fn_disease_cd = ''{addition_tar_cd}'' and fn_class_cd=''0''))) end end ', '', 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('pat_event', 'bbs_ctl_no', '', 'case when ''{bbs_ctl_no}'' = ''null'' or ''{bbs_ctl_no}''=''''  THEN 0 else (select  COALESCE(max(bbs_ctl_no),0) from  bbs_info where fn_seq_id::text=''{bbs_ctl_no}'' and facility_cd = ''{facility_cd}'') end', '', 'SQL' );
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('ord_main','rst_equip_info','class_type','(SELECT  b.class_type FROM mst_equipment a INNER JOIN mst_equipment_class b on a.class_cd=b.class_cd WHERE  a.facility_cd = ''{facility_cd}'' AND a.fn_equipment_cd :: CHARACTER VARYING = ''{class_type}'') ','','SQL');
