INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_graph_setting','value','','CASE when ''{graph_setting_no}'' =''34'' or ''{graph_setting_no}'' =''35'' or ''{graph_setting_no}'' =''36'' or ''{graph_setting_no}'' =''37'' or ''{graph_setting_no}'' =''38'' or ''{graph_setting_no}'' =''39'' or ''{graph_setting_no}'' =''40'' or ''{graph_setting_no}'' =''41'' or ''{graph_setting_no}'' =''42'' then (select  pat_group_cd::TEXT from pat_group where facility_cd=''{facility_cd}'' and fn_pat_group_cd= ''{value}'') when ''{graph_setting_no}''=''2'' or''{graph_setting_no}''=''3'' then (select  COALESCE(max(exam_item_cd),0) ::text from  mst_exam_item  where facility_cd=''{facility_cd}'' and fn_exam_item_cd=''{value}'') else  ''{value}'' end','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES  ('mnt_mainte_main', 'mainte_layout_cd', NULL, '(SELECT mainte_layout_cd FROM mst_mainte_layout WHERE facility_cd = ''{facility_cd}'' AND layout_name :: character varying = ''{mainte_layout_cd}'' and  layout_class=''{mainte_class}'' ) ', NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_mainte_layout','detail_info_1','cd','case when {layout_class}=2 then (select mainte_category_cd from mst_mainte_category where facility_cd = ''{facility_cd}'' and  fn_mainte_category_cd=''{cd}'' and  mainte_class=''2'' and  fn_mainte_type=''1'') else (select mainte_category_cd from mst_mainte_category where facility_cd = ''{facility_cd}'' and  fn_mainte_category_cd=''{cd}'' and  mainte_class=''1'' and  fn_mainte_type=''0'') end ','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_mainte_layout','detail_info_2','cd','(select mainte_category_cd from mst_mainte_category where facility_cd = ''{facility_cd}'' and  fn_mainte_category_cd=''{cd}'' and  mainte_class=''2'' and  fn_mainte_type=''2'')','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('mnt_mainte_main', 'detail_mainte', 'detail_cd', '(select mainte_detail_cd from mst_mainte_detail where facility_cd = ''{facility_cd}'' and  fn_mainte_type=''{tableIndex}'' and ( fn_mainte_detail_cd like ''{detail_cd}'' or fn_mainte_detail_cd like ''{detail_cd},%'' or fn_mainte_detail_cd like ''%,{detail_cd},%'' or fn_mainte_detail_cd like ''%,{detail_cd}''))', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('mnt_mainte_main', 'detail_mainte', 'cate_cd', '(select mainte_category_cd from mst_mainte_category where facility_cd = ''{facility_cd}'' AND fn_mainte_type = ''{tableIndex}'' AND (fn_mainte_category_cd LIKE ''{cate_cd}'' OR fn_mainte_category_cd LIKE ''%,{cate_cd},%'' OR fn_mainte_category_cd LIKE ''{cate_cd},%'' OR fn_mainte_category_cd LIKE ''%,{cate_cd}''))', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('mnt_mainte_main', 'detail', 'detail_cd', 'case when {mainte_class}=1 then (select mainte_detail_cd from mst_mainte_detail where facility_cd = ''{facility_cd}'' and  fn_mainte_detail_cd=''{detail_cd}'' and  mainte_class=''{mainte_class}'') else (select mainte_detail_cd from mst_mainte_detail where facility_cd = ''{facility_cd}'' and  fn_mainte_type=''{tableIndex}'' and ( fn_mainte_detail_cd like ''{detail_cd}'' or fn_mainte_detail_cd like ''{detail_cd},%'' or fn_mainte_detail_cd like ''%,{detail_cd},%'' or fn_mainte_detail_cd like ''%,{detail_cd}'')) end', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('mnt_mainte_main', 'detail', 'detail_edi', '(select edition_no from mst_mainte_detail where facility_cd = ''{facility_cd}'' and  fn_mainte_detail_cd=''{detail_edi}'' and  mainte_class=''{mainte_class}'')', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('mnt_mainte_main', 'detail', 'cate_cd', 'case when {mainte_class}=1 then (select mainte_category_cd from mst_mainte_category where facility_cd = ''{facility_cd}'' and  fn_mainte_category_cd like ''%{cate_cd}%'' and mainte_class=''{mainte_class}'') else (select mainte_category_cd from mst_mainte_category where facility_cd = ''{facility_cd}'' AND fn_mainte_type = ''{tableIndex}'' AND (fn_mainte_category_cd LIKE ''{cate_cd}'' OR fn_mainte_category_cd LIKE ''%,{cate_cd},%'' OR fn_mainte_category_cd LIKE ''{cate_cd},%'' OR fn_mainte_category_cd LIKE ''%,{cate_cd}'')) end', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('mnt_mainte_main', 'detail', 'cate_edi', 'case when {mainte_class}=1 then (select edition_no from mst_mainte_category where facility_cd = ''{facility_cd}'' and  fn_mainte_category_cd like ''%{cate_edi}%'' and  mainte_class=''{mainte_class}'') else {cate_edi} end', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('mnt_mainte_main', 'detail', NULL, '(json_build_array (VARIADIC ARRAY [{detail_mainte},{detail_parts}]))', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('mnt_mainte_main', 'detail_parts', 'cate_cd', '(select mainte_category_cd from mst_mainte_category where facility_cd = ''{facility_cd}'' AND fn_mainte_type = ''{tableIndex}'' AND (fn_mainte_category_cd LIKE ''{cate_cd}'' OR fn_mainte_category_cd LIKE ''%,{cate_cd},%'' OR fn_mainte_category_cd LIKE ''{cate_cd},%'' OR fn_mainte_category_cd LIKE ''%,{cate_cd}''))', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('mnt_mainte_main', 'detail_parts', 'detail_cd', '(select mainte_detail_cd from mst_mainte_detail where facility_cd = ''{facility_cd}'' and  fn_mainte_type=''{tableIndex}'' and ( fn_mainte_detail_cd like ''{detail_cd}'' or fn_mainte_detail_cd like ''{detail_cd},%'' or fn_mainte_detail_cd like ''%,{detail_cd},%'' or fn_mainte_detail_cd like ''%,{detail_cd}'') and trim(mainte_content_3) like ''%{change_period}h'')', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('mnt_mainte_main', 'mainte_layout_edition', NULL, 'case when ''{mainte_layout_edition}'' = '''' then null else 1 end', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('mnt_mainte_main', 'mainte_category_cd', 'mainteCategoryCd', '(SELECT mainte_category_cd FROM mst_mainte_category WHERE facility_cd = ''{facility_cd}'' AND fn_mainte_category_cd :: CHARACTER VARYING like ''%{mainteCategoryCd}%'' AND mainte_class = ''1'')', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE (NTSS_TABLE_NAME, NTSS_COLUMN_NAME, NTSS_JSON_NAME, CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_job', 'default_menu_settings', '', 'json_build_object(''initial_menu_function'', ''020'', ''default_menu_functions'', json_build_array (VARIADIC ARRAY [(SELECT array_agg(info->>''func_cd'')	AS func_cd FROM mst_facility as a CROSS JOIN LATERAL JSON_array_elements((a.use_function->>''func_cds'')::JSON)  info WHERE  facility_cd =''{facility_cd}'') ])  )', '','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_com_fixed_phrase', 'occupations', '', '(select  array_to_json(array_agg(job_cd)) from  mst_job where facility_cd=''{facility_cd}'' and is_disp=''1'')', '', 'SQL');
