INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'rst_treatment_info', 'treat_medicine_cd', 'CASE ''{medicine_type}'' WHEN ''1'' THEN (SELECT medicine_cd FROM mst_medicine WHERE facility_cd = ''{facility_cd}'' AND fn_medicine_cd = ''{treat_medicine_cd}'') WHEN ''2'' THEN (SELECT medicine_mix_cd ::int FROM mst_medicine_mix WHERE facility_cd = ''{facility_cd}'' AND fn_set_medicine_cd = ''{treat_medicine_cd}'') END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_cond_info', 'unit', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN (case when ''{unit}'' = ''null'' then null else ''{unit}'' end) else (case when ''{key}'' in (''6'', ''7'', ''8'', ''9'', ''10'', ''11'', ''13'') then (select unit from mst_equipment where facility_cd = ''{facility_cd}'' AND fn_equipment_cd = ''{value}'') when ''{key}'' in (''15'', ''19'', ''25'') then (select unit from mst_medicine where facility_cd = ''{facility_cd}'' AND fn_medicine_cd = ''{value}'') when ''{key}'' in (''17'', ''22'', ''26'', ''28'') then (select unit from mst_medicine where facility_cd = ''{facility_cd}'' AND fn_medicine_cd = ''{value_conv}'') when ''{key}'' = ''27'' then (select unit||''/h'' from mst_medicine where facility_cd = ''{facility_cd}'' AND fn_medicine_cd = ''{value_conv}'') else ''{unit}'' end) END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_cond_info', 'value_name_1', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN (case when ''{value_name_1}'' = ''null'' then null else ''{value_name_1}'' end) else (case when ''{key}'' = ''2'' then (select va_name from mst_va where facility_cd = ''{facility_cd}'' AND fn_va_cd = ''{value}'') when ''{key}'' = ''5'' then (select model_number from mst_dialyzer where facility_cd = ''{facility_cd}'' AND fn_dialyzer_cd = ''{value}'') when ''{key}'' in (''6'', ''7'', ''8'', ''9'', ''10'', ''11'', ''13'') then (select equipment_name from mst_equipment where facility_cd = ''{facility_cd}'' AND fn_equipment_cd = ''{value}'') when ''{key}'' in (''15'', ''19'', ''25'') then (select medicine_name from mst_medicine where facility_cd = ''{facility_cd}'' AND fn_medicine_cd = ''{value}'') else ''{value_name_1}'' end) END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_cond_info', 'value_name_2', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN (case when ''{value_name_2}'' = ''null'' then null else ''{value_name_2}'' end) else (case when ''{key}'' = ''5'' then (select maker from mst_dialyzer where facility_cd = ''{facility_cd}'' AND fn_dialyzer_cd = ''{value}'') else ''{value_name_2}'' end) END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_cond_info', 'input_class', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN {input_class} else 1 END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_medi_info', 'class_cd', 'CASE ''{medicine_type}'' WHEN ''0'' then (SELECT class_cd FROM mst_medicine WHERE facility_cd = ''{facility_cd}'' AND fn_medicine_cd = ''{cd}'') else (SELECT class_cd FROM mst_medicine_mix WHERE facility_cd = ''{facility_cd}'' AND fn_set_medicine_cd = ''{cd}'') END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_medi_info', 'class_name', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN (case when ''{class_name}'' = ''null'' then null else ''{class_name}'' end) ELSE CASE ''{medicine_type}'' WHEN ''0'' then (SELECT mstc.class_name FROM mst_medicine_class mstc INNER JOIN mst_medicine mst ON mst.facility_cd = mstc.facility_cd AND mst.class_cd = mstc.class_cd WHERE mst.facility_cd = ''{facility_cd}'' AND mst.fn_medicine_cd = ''{cd}'') else (SELECT class_name FROM mst_medicine_class mstc INNER JOIN mst_medicine_mix mst ON mst.facility_cd = mstc.facility_cd AND mst.class_cd = mstc.class_cd  WHERE mst.facility_cd = ''{facility_cd}'' AND mst.fn_set_medicine_cd = ''{cd}'') END END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_medi_info', 'class_type', 'CASE ''{medicine_type}'' WHEN ''0'' then (SELECT mstc.class_type FROM mst_medicine_class mstc INNER JOIN mst_medicine mst ON mst.facility_cd = mstc.facility_cd AND mst.class_cd = mstc.class_cd WHERE mst.facility_cd = ''{facility_cd}'' AND mst.fn_medicine_cd = ''{cd}'') else (SELECT mstc.class_type FROM mst_medicine_class mstc INNER JOIN mst_medicine_mix mst ON mst.facility_cd = mstc.facility_cd AND mst.class_cd = mstc.class_cd  WHERE mst.facility_cd = ''{facility_cd}'' AND mst.fn_set_medicine_cd = ''{cd}'') END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_medi_info', 'name', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN (case when ''{name}'' = ''null'' then null else ''{name}'' end) ELSE CASE ''{medicine_type}'' WHEN ''0'' then (SELECT medicine_name FROM mst_medicine WHERE facility_cd = ''{facility_cd}'' AND fn_medicine_cd = ''{cd}'') else (SELECT medicine_mix_name FROM mst_medicine_mix WHERE facility_cd = ''{facility_cd}'' AND fn_set_medicine_cd = ''{cd}'') END END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_medi_info', 'short_name', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN (case when ''{short_name}'' = ''null'' then null else ''{short_name}'' end) ELSE CASE ''{medicine_type}'' WHEN ''0'' then (SELECT mstc.class_name FROM mst_medicine_class mstc INNER JOIN mst_medicine mst ON mst.facility_cd = mstc.facility_cd AND mst.class_cd = mstc.class_cd WHERE mst.facility_cd = ''{facility_cd}'' AND mst.fn_medicine_cd = ''{cd}'') else (SELECT class_name FROM mst_medicine_class mstc INNER JOIN mst_medicine_mix mst ON mst.facility_cd = mstc.facility_cd AND mst.class_cd = mstc.class_cd  WHERE mst.facility_cd = ''{facility_cd}'' AND mst.fn_set_medicine_cd = ''{cd}'') END END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_medi_info', 'timing_name', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN (case when ''{timing_name}'' = ''null'' then null else ''{timing_name}'' end) else (SELECT medicate_timing_name FROM mst_medicate_timing WHERE facility_cd = ''{facility_cd}'' AND fn_medicate_timing_cd = ''{timing_cd}'') END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_medi_info', 'procedure_name', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN (case when ''{procedure_name}'' = ''null'' then null else ''{procedure_name}'' end) else (SELECT pricedure_name FROM mst_procedure WHERE facility_cd = ''{facility_cd}'' AND fn_procedure_cd = ''{procedure_cd}'') END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_medi_info', 'unit', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN (case when ''{unit}'' = ''null'' then null else ''{unit}'' end) ELSE CASE ''{medicine_type}'' WHEN ''0'' then (SELECT unit FROM mst_medicine WHERE facility_cd = ''{facility_cd}'' AND fn_medicine_cd = ''{cd}'') else (SELECT unit FROM mst_medicine_mix WHERE facility_cd = ''{facility_cd}'' AND fn_set_medicine_cd = ''{cd}'') END END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_equip_info', 'class_cd', '(SELECT class_cd FROM mst_equipment WHERE facility_cd = ''{facility_cd}'' AND fn_equipment_cd = ''{cd}'')', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_equip_info', 'class_name', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN (case when ''{class_name}'' = ''null'' then null else ''{class_name}'' end) else (SELECT class_name FROM mst_equipment_class class inner join mst_equipment mst ON class.facility_cd = mst.facility_cd AND class.class_cd = mst.class_cd WHERE mst.facility_cd = ''{facility_cd}'' AND mst.fn_equipment_cd = ''{cd}'') END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_equip_info', 'class_type', '(SELECT class_type FROM mst_equipment_class class inner join mst_equipment mst ON class.facility_cd = mst.facility_cd AND class.class_cd = mst.class_cd WHERE mst.facility_cd = ''{facility_cd}'' AND mst.fn_equipment_cd = ''{cd}'')', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_equip_info', 'name', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN (case when ''{name}'' = ''null'' then null else ''{name}'' end) else (SELECT equipment_name FROM mst_equipment WHERE facility_cd = ''{facility_cd}'' AND fn_equipment_cd = ''{cd}'') END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_equip_info', 'short_name', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN (case when ''{short_name}'' = ''null'' then null else ''{short_name}'' end) else (SELECT equipment_name FROM mst_equipment WHERE facility_cd = ''{facility_cd}'' AND fn_equipment_cd = ''{cd}'') END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_equip_info', 'unit', 'CASE WHEN ''{rst_dialysis_state}'' = ''6'' THEN (case when ''{unit}'' = ''null'' then null else ''{unit}'' end) else (SELECT unit FROM mst_equipment WHERE facility_cd = ''{facility_cd}'' AND fn_equipment_cd = ''{cd}'') END', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_facility_setting','value','','CASE when ''{facility_setting_no}'' =''1028''  then (select procedure_cd::TEXT from  mst_procedure where  fn_procedure_cd=''{value}'' and facility_cd = ''{facility_cd}'' ) when ''{facility_setting_no}'' =''1029'' then (select medicate_timing_cd::TEXT  from mst_medicate_timing where  fn_medicate_timing_cd=''{value}'' and facility_cd = ''{facility_cd}'')  when ''{facility_setting_no}'' =''3006'' or ''{facility_setting_no}'' =''3007'' then ''["{value}"]''  else  ''{value}'' end','','SQL');
