INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_treatment_status_layout','dcs_view_items','data_type','CASE WHEN {data_class}<-10000 THEN (case when {data_class}<-504851 then (select data_type :: TEXT from sys_monitor_item where moni_data_no = ''Z{data_type}'') else (select data_type :: TEXT from sys_monitor_item where moni_data_no = ''{data_type}'') end) else '''' END','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_treatment_status_layout','dcs_view_items','conv_type','CASE WHEN {data_class}<-10000 THEN (case when {data_class}<-504851 then (SELECT  CASE WHEN  conv_item IS  NULL THEN ''0'' ELSE ''1'' END FROM sys_monitor_item WHERE moni_data_no = ''Z{conv_type}'') else (SELECT  CASE WHEN  conv_item IS  NULL THEN ''0'' ELSE ''1'' END FROM sys_monitor_item WHERE moni_data_no = ''{conv_type}'') end) WHEN {data_class}>=10000 THEN ''0'' else (select data_class::TEXT from mst_treatment_status_disp_item where item_cd={data_class}) END','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_treatment_status_layout','dcs_view_items','key_name','CASE WHEN {data_class}<-10000 THEN (case when {data_class}<-504851 then ''Z{key_name}'' else ''{key_name}'' end) WHEN {data_class}>=10000 THEN (select (10000 + vital_monitor_item_cd)::TEXT from mst_add_monitor where fn_vital_monitor_item_cd = {data_class} and facility_cd = ''{facility_cd}'') else (select json_key_name::TEXT from mst_treatment_status_disp_item where item_cd={data_class}) END','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_treatment_status_layout','dcs_view_items','data_class','CASE WHEN {data_class}>=10000 THEN (select 10000 + vital_monitor_item_cd from mst_add_monitor where fn_vital_monitor_item_cd = {data_class} and facility_cd = ''{facility_cd}'') else {data_class} END','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_treatment_status_layout','dcs_view_items','column_name','CASE  WHEN {data_class}<-10000 OR {data_class} >= 10000 THEN ''monitor_data'' else (select field_name::TEXT from mst_treatment_status_disp_item where item_cd={data_class})   END','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_treatment_status_layout','dcs_view_items','table_name','CASE WHEN {data_class}<-10000 THEN ''mni_monitor'' WHEN {data_class}>= 10000 THEN ''mni_monitor'' else  (select table_name::TEXT from mst_treatment_status_disp_item where item_cd={data_class})  END','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_treatment_status_layout','dcs_view_items','vital_monitor_class','CASE WHEN ''{data_class}'' in(''-15748'',''-15749'',''-15750'',''-15751'',''-15752'') THEN ''1'' ELSE ''2''  END','','SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('pat_main_history','addition_info','last_date','case when ''{last_date}''=''null'' then '''' else ''{last_date}'' end','','SQL');
