INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('ord_coop_no','user_id','','(CASE WHEN ''{coop_cd}'' = ''ind_dial'' THEN (select (ind_schedule_user_info->>''ind_user_id'')::INTEGER from ord_main where facility_cd=''{facility_cd}'' and treat_date=(select substr(''{ord_no}'', 1, 8)) and fn_pat_id:: CHARACTER VARYING = substr(''{ord_no}'', 16, 12) and fn_plural:: TEXT = substr(''{ord_no}'', 28, 1):: TEXT LIMIT 1 ) WHEN ''{coop_cd}''  IN (''rep_dial'',''rst_dial'') then   (select up_ind_user_id from ord_main where facility_cd=''{facility_cd}'' and rst_fn_dialysis_no=(select substr(''{ord_no}'', 0, 13):: int8))  ELSE NULL END)', '', 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('ord_main', 'ind_treat_start_time', '', 'case when ''{ind_treat_start_time}'' ='''' then ( select LEFT(kur_standard_start_time, 4)  from mst_kur where facility_cd = ''{facility_cd}'' and fn_kur_cd=''{ind_kur_cd}'' ) else ''{ind_treat_start_time}'' end', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('pat_treatment_pattern', 'ind_sch_info', 'ind_treat_start_time', 'case when ''{ind_treat_start_time}'' =''null'' then ( select LEFT(kur_standard_start_time, 4)  from mst_kur where facility_cd = ''{facility_cd}'' and fn_kur_cd=''{ind_kur_cd}'' ) else ''{ind_treat_start_time}'' end', NULL, NULL, 'SQL');
INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONV_VALUE_3,CONVERSION_TYPE) VALUES ('mst_pat_calendar_layout', 'disp_item_info', '', 'json_build_array(json_build_object(''isDisp'',true,''dataKey'',''treat_info'',''dispGroup'',''treat_plan'',''categoryNo'',2,''categoryItem'',json_build_array(json_build_object(''isDisp'',false,''subCategoryNo'',1,''subCategoryItem'',json_build_array(json_build_object(''isDisp'',true,''itemNo'',100,''itemKey'',''treatmentName'',''itemName'',''治療方法''),json_build_object(''isDisp'',true,''itemNo'',101,''itemKey'',''kurName'',''itemName'',''クール''),json_build_object(''isDisp'',true,''itemNo'',102,''itemKey'',''startDate'',''itemName'',''治療開始時刻'')', ',json_build_object(''rstCd'',1,''isDisp'',true,''itemNo'',103,''itemKey'',''rstEndDate'',''itemName'',''治療終了時刻'')),''subCategoryName'',''治療予定'')),''categoryName'',''治療情報''),json_build_object(''isDisp'',true,''categoryNo'',3,''categoryItem'',json_build_array(json_build_object(''isDisp'',true,''dataKey'',''exam_request'',''dispGroup'',''exam_request'',''subCategoryNo'',2,''subCategoryItem'',json_build_array(),''subCategoryName'',''検査予定''),json_build_object(''isDisp'',true,''dataKey'',''exam_result'',''dispGroup'',''exam_result'',''subCategoryNo'',1,''subCategoryItem'',json_build_array(),''subCategoryName'',''検査結果'')),''categoryName'',''検査''),json_build_object(''isDisp'',true,''categoryNo'',5,''categoryItem'',json_build_array(json_build_object(''isDisp'',true,''dataKey'',''pat_event'',''dispGroup'',''pat_event'',''subCategoryNo'',1,''subCategoryItem'',(SELECT COALESCE(json_agg(json_build_object(''isDisp'', 1,''itemNo'', sub_category_cd::int,''itemName'', sub_category_name,''isPatEventSub'', 1) ORDER BY sub_category_cd),''[]''::json) AS result_json FROM mst_pat_event_sub_category WHERE facility_cd = ''{facility_cd}'' and fn_event_category_class=''0''),''subCategoryName'',''患者イベント'')),''categoryName'',''患者イベント''))', NULL, 'SQL');
