--INSERT INTO SYNC_CUSTOM_CONVERT_VALUE(NTSS_TABLE_NAME,NTSS_COLUMN_NAME,NTSS_JSON_NAME,CONV_VALUE_1,CONV_VALUE_2,CONVERSION_TYPE) VALUES ('mst_addition', 'addition_tar_cd', '', 'case when ''{addition_tar_cd}'' is null or ''{addition_tar_cd}''=''''  THEN ''[]'' else json_build_array(json_build_object(''cd'',(select disease_cd from mst_disease where facility_cd = ''{facility_cd}'' AND fn_disease_cd = ''{addition_tar_cd}''),''name'',(select disease_name from mst_disease where facility_cd = ''{facility_cd}'' AND fn_disease_cd = ''{addition_tar_cd}''))) end', '', 'SQL' );
