UPDATE SYNC_CUSTOM_CONVERT_VALUE SET CONV_VALUE_1='CASE when ''{va_flg}''=''1'' then case when {image_count}!=0 then (select json_build_array(json_build_object ( ''format_class'', 2,''va_cd'', CASE WHEN ''{name}''=''null'' or ''{name}''='''' then null else case when (select count(*) from  mst_va where facility_cd = ''{facility_cd}'' AND va_name = ''{name}'')>1 then null  else (select va_cd from mst_va where facility_cd = ''{facility_cd}'' AND va_name = ''{name}'' ) end end ,''va_name'', CASE WHEN ''{name}''=''null'' or ''{name}''='''' then '''' else ''{name}'' end, ''result_value'',{result_value_2} ),json_build_object(''format_class'',1,''result_value'',''{result_value_1}''),json_build_object(''format_class'', 5, ''result_value'', CASE WHEN ''{make_date}'' != ''null'' AND ''{make_date}'' != '''' THEN TO_CHAR(TO_TIMESTAMP(''{make_date}'', ''YYYY/MM/DD HH24:MI:SS''), ''YYYY-MM-DD'') ELSE null END),json_build_object(''format_class'',7,''result_value'',case when ''{rv7_file_name}''!=''null'' and ''{rv7_file_name}''!='''' then json_build_array(json_build_object(''file_path'',''/{facility_cd}/{pat_id}/{folder_name}/{rv7_file_name}'',''file_name'',''{rv7_file_name}'',''old_full_file_name'',''{old_full_rv7_file_name}''))else json_build_array() end),json_build_object(''upDate'',''{upDate}'')   )) else (select json_build_array(json_build_object(''format_class'',1,''result_value'',''''),json_build_object(''format_class'', 5, ''result_value'', CASE WHEN ''{make_date}'' != ''null'' AND ''{make_date}'' != '''' THEN TO_CHAR(TO_TIMESTAMP(''{make_date}'', ''YYYY/MM/DD HH24:MI:SS''), ''YYYY-MM-DD'') ELSE null END),json_build_object(''format_class'',7,''result_value'',case when ''{rv7_file_name}''!=''null'' and ''{rv7_file_name}''!='''' then json_build_array(json_build_object(''file_path'',''/{facility_cd}/{pat_id}/{folder_name}/{rv7_file_name}'',''file_name'',''{rv7_file_name}'',''old_full_file_name'',''{old_full_rv7_file_name}''))else json_build_array() end),json_build_object(''upDate'',''{upDate}''))) end' WHERE NTSS_TABLE_NAME = 'pat_event' AND NTSS_COLUMN_NAME = 'result_params';
